<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigEnabledUserEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigEnabledUserEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigEnabledUserEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getEnabledUserEmail returns null on a freshly created holder.
     */
    public function testEnabledUserEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnabledUserEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isEnabledUserEmailAssigned());
        $this->assertNull($holder->getEnabledUserEmail());
    }
}
class ImplWithTenantConfigEnabledUserEmailAttributeHolderUnitTest
{
    use TenantConfigEnabledUserEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedEnabledUserEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultEnabledUserEmail();
    }
}
